"""Author original lesson challenges. Output protected answers outside the Pages tree.
Families are deliberately different from the worked-example drills, with explicit
conditions and checks. Parameter variants are practice, not new structural mastery.
Run: python tools/content/build_original_lessons.py SESSION_MAP OUTPUT_DIR
"""
import json, math, itertools, sys
from pathlib import Path
from fractions import Fraction
C=math.comb

def ordinal(n):
    return str(n)+('th' if 10<n%100<14 else {1:'st',2:'nd',3:'rd'}.get(n%10,'th'))

def task(prompt, answer, steps, check, clue):
    return dict(prompt=prompt,answer=answer,steps=steps,check=check,clue=clue)

def family(k,n,role):
    # n=3..11 (visit+2); all tasks are authored here, not drawn from an exam bank.
    x=n+4
    if k=='DIG-01':
        if role=='try': return task(f'A school bookshop sells packs of stickers for 99 cents each. A student buys {x} packs and a pencil costing 37 cents. What is the total cost in cents?',99*x+37,[f'Pretend each sticker pack costs 100 cents: {100*x}.',f'Remove the {x} extra cents, then add 37: {99*x+37}.'],'Estimate using one dollar per sticker pack; the actual total is slightly greater because of the pencil.','Several numbers are close to a convenient place-value boundary.')
        # Distinct concrete contexts; the consistent error is 2 items per batch.
        contexts={
            7:f'A warehouse already has 53 batteries in stock. It receives {x} boxes containing 198 batteries each. Its stock system mistakenly records 200 batteries per box, so the total on the screen is {200*x+53}. What should the correct stock total be?',
            8:f'A ticket printer has already printed 53 tickets. It then prints {x} batches of 198 tickets. A faulty counter adds 200 tickets after each batch and ends at {200*x+53}. How many tickets were actually printed altogether?',
            9:f"A game's scoreboard starts at 53 points. Over the next {x} rounds, a player earns 198 points per round, but the scoreboard mistakenly adds 200 points each time. Its final reading is {200*x+53}. What should the correct score be?",
            10:f'A factory already has 53 finished parts recorded. It produces {x} new batches, each containing exactly 198 parts. The computer incorrectly records 200 parts per batch, so it displays {200*x+53} parts. How many finished parts should the computer show?'
        }
        story=contexts.get(x,f'A warehouse starts with 53 batteries. It receives {x} boxes with 198 batteries in each box, but its computer incorrectly adds 200 per box and displays {200*x+53}. What is the correct total?')
        return task(story,198*x+53,[f'Each batch is overcounted by 200 − 198 = 2 items.',f'The total error is {x} × 2 = {2*x} items.',f'Correct the displayed total: {200*x+53} − {2*x} = {198*x+53}.'],f'Check against the starting 53: 53 + {x} × 198 = {198*x+53}.','A repeated small error can be corrected before doing long multiplication.')
    if k=='DIG-02':
        digits=sorted([0]+[((n+d)%9)+1 for d in [0,2,5,7]])
        if role=='try':
            values=[100*a+10*b+c for a,b,c in itertools.permutations(digits,3) if a and c%2==0]
            return task(f'Remember that a three-digit number cannot begin with 0. Using the digits {", ".join(map(str,digits))}, how many different three-digit even numbers can you make without repeating any digit?',len(values),['Separate endings of zero from nonzero even endings. Zero changes how many first digits are allowed.',f'Count the remaining middle choices in each case and add: {len(values)}.'],'List each legal ending and check that no number begins with zero.','The last digit controls evenness; zero changes the first-place choices.')
        digits=[0,1,2,5,7,n];digits=sorted(set(digits))
        val=sum(a!=0 and 100*a+10*b+c>500 and a<c for a,b,c in itertools.permutations(digits,3))
        return task(f'Choose three different digits from {", ".join(map(str,digits))}. How many three-digit codes are greater than 500 and have a first digit smaller than the last digit?',val,['List possible first digits satisfying the size condition. For each, list allowed larger last digits.',f'Every first/last pair leaves {len(digits)-2} middle digits. Add the cases: {val}.'],'Recover each code from its first and last digits, so cases cannot overlap.','Two different positions must meet linked restrictions; multiplying unrestricted choices would overcount.')
    if k=='DIG-03':
        lo=100*n+20;hi=lo+39;d=2
        if role=='try':
            val=sum(str(i).count(str(d)) for i in range(lo,hi+1))
            return task(f'A printer labels drawers {lo} through {hi}, inclusive. How many copies of the digit 2 does it print?',val,['Count the hundreds, tens and units columns separately.',f'The total number of copies is {val}; a label containing two 2s contributes twice.'],'Write the first and last labels and count each position independently.','We are counting printed digits, not labels that contain a digit.')
        start=100*x+87;end=start+26;val=sum(len(str(i)) for i in range(start,end+1))
        lengths={d:sum(len(str(i))==d for i in range(start,end+1)) for d in sorted(set(len(str(i)) for i in range(start,end+1)))}
        breakdown=' + '.join(f'{count} × {d}' for d,count in lengths.items())
        return task(f'A ticket printer prints every ticket number from {start} to {end}, including both endpoints. Each number is printed once. How many individual digits does the printer print altogether?',val,[f'Count the numbers including both endpoints: {end} − {start} + 1 = {end-start+1}.',f'Group the numbers by how many digits they contain; calculate {breakdown} = {val} printed digits.'],f'Check all ticket numbers from {start} through {end}, counting any change in number length only once.','The count is the total number of printed digits, not merely the number of tickets.')
    if k=='DIG-04':
        if role=='try':
            total=2*(n+3);vals=[1000*a+100*b+10*b+a for a in range(1,10) for b in range(10) if 2*(a+b)==total]
            return task(f'How many four-digit palindromes have digit sum {total}? A palindrome reads the same backwards.',len(vals),[f'Write ABBA. The sum is 2A + 2B, so A + B = {total//2}.',f'Count A from 1 to 9 with B = {total//2} − A between 0 and 9: {len(vals)}.'],'A cannot be zero. Each allowed pair gives exactly one palindrome.','Mirroring links digit positions, so only half are free.')
        lower=1000+137*n;vals=[i for i in range(lower,lower+600) if str(i)==str(i)[::-1]];a=min(vals)
        return task(f'A display must show a four-digit palindrome strictly greater than {lower}. What is the smallest possible display?',a,['Mirror the first two digits of the lower bound.',f'If that is not strictly greater, increase the first half by one and mirror again. The result is {a}.'],'The previous mirrored first half is too small; later halves give larger numbers.','Build the smallest legal first half, rather than searching every four-digit number.')
    if k=='DIG-05':
        a=n%5+4;b=n%4+2;v=2*(10*b+a)
        if role=='try':return task(f'The symbol {b}A represents a two-digit number with tens digit {b} and units digit A. If {b}A + {b}A = {v}, what digit is A?',a,[f'{b}A means {10*b} + A.',f'Subtract the two tens contributions: {v} − {20*b} = {2*a}; halve to get {a}.'],f'Check the actual addition {10*b+a} + {10*b+a} = {v}, including any carry.','A letter occupies a place-value column; a carry must be consistent.')
        a=n%7+2;v=10*a+7+70+a
        return task(f'Two two-digit numbers are A7 and 7A. Their sum is {v}. What digit is A?',a,['Write the sum as (10A + 7) + (70 + A) = 11A + 77.',f'Subtract 77 and divide by 11: A = {a}.'],f'Substitute the digit into both numbers and add; also check A is nonzero.','The same digit contributes different amounts in two positions.')
    if k=='DIV-01':
        if role=='try':
            N=2**(n-1)*3*5;val=(n)*2*2-2
            return task(f'{N} tiles must be split into equal groups with more than one tile per group and more than one group. How many different group sizes are possible?',val,[f'{N} = 2^{n-1} × 3 × 5, giving {(n)*4} divisors.',f'Remove group sizes 1 and {N}; {val} remain.'],'Every allowed divisor determines one legal grouping.','Equal grouping is a divisor question with excluded endpoints.')
        N=2**(n-1)*3**3;ans=2**((n-1)%2)*3
        return task(f'A square mosaic must use all {N} tiles plus some identical full packs of {N} tiles. What is the smallest total number of packs, counting the first pack, that gives a square number of tiles?',ans,[f'Factor {N} = 2^{n-1} × 3³.',f'A square needs even prime exponents. Multiply by {ans} to pair the odd exponents.'],'The completed product is a square; omitting any required prime leaves an odd exponent.','The target is a perfect square, so count prime copies rather than just divisors.')
    if k=='DIV-02':
        if role=='try':return task(f'Two clocks beep together at 09:00. One beeps every {2*x} minutes and one every {3*x} minutes. How many times do they beep together during the next {18*x} minutes, excluding 09:00 but including the end?',3,[f'The common period is lcm({2*x}, {3*x}) = {6*x} minutes.',f'The next coincidences are {6*x}, {12*x}, {18*x} minutes: 3.'],'The starting coincidence is excluded and the endpoint is included.','First find the common period, then count events within the stated interval.')
        return task(f'A beacon flashes at minutes {n}, {n+6}, {n+12}, … . Another flashes at minutes {n+4}, {n+12}, {n+20}, … . What is the first minute greater than {n+12} when both flash?',n+36,[f'They first coincide at {n+12}; after that the common period is lcm(6,8)=24.',f'The next shared time is {n+12}+24={n+36}.'],'Check the answer is in both lists; lcm alone is a gap, not the first time.','Different start times matter as well as repeating periods.')
    if k=='DIV-03':
        if role=='try':
            val=n%6+1
            return task(f'A warehouse packs {7*x+val} bolts into boxes that each hold exactly 7 bolts. After filling as many boxes as possible, how many additional bolts are needed to fill the final, partly filled box?',7-val,[f'The leftover is {val}, since {7*x+val} = 7 × {x} + {val}.',f'The space left in a batch is 7 − {val} = {7-val}.'],'Adding the answer must produce a multiple of 7.','The requested amount is the complement of the remainder.')
        a=3+n%3;b=n+1;val=(a*a+b)%7
        return task(f'A whole number N leaves remainder {a} when divided by 7. What remainder does N × N + {b} leave when divided by 7?',val,[f'Write N = 7k + {a}. All terms of the square except {a*a} contain a factor 7.',f'Reduce {a*a}+{b} modulo 7 to get {val}.'],f'Try N={a+7} and N={a+14}; both checks agree, while the expansion proves the general claim.','We need only the remainder class, not the unknown number itself.')
    if k=='DIV-04':
        if role=='try':
            moves=2*n+1
            return task(f'A row has {2*n} blue lamps and no other lamps. A move changes exactly three lamps to the opposite colour (blue to gold or gold to blue). After exactly {moves} moves, can every lamp be blue again? Answer yes or no.','no',['Each move changes the parity of the number of gold lamps because it flips an odd number of lamps.',f'An odd number ({moves}) of moves changes even parity to odd. Zero gold lamps is even.'],'The argument follows parity, not the particular lamps chosen.','A move changes a count but always changes its parity in the same way.')
        return task(f'A counter starts at {3*x+1}. Each move adds 6 or subtracts 9. Can it ever reach {6*x+2}? Answer yes or no.','no',[f'The start leaves remainder 1 on division by 3. Both allowed changes are multiples of 3.',f'The target {6*x+2} leaves remainder 2, so it cannot be reached.'],'Every possible sequence preserves the remainder; checking a few moves alone would not prove impossibility.','Find a property every legal move preserves.')
    if k=='DIV-05':
        exponent=4*n+3
        if role=='try':return task(f'A code is the units digit of 3^{exponent} + 2. What is the code?',9,[f'Powers of 3 end 3, 9, 7, 1 in a cycle of 4. {exponent} leaves remainder 3.', 'The power ends in 7; adding 2 gives units digit 9.'],'Track the exponent from 1, not 0.','A huge power may have a short repeating units-digit cycle.')
        e=4*n+2;ans=(pow(7,e,10)+pow(3,e+1,10))%10
        return task(f'What is the last digit of 7^{e} + 3^{e+1}?',ans,[f'Reduce both exponents modulo 4. The two powers end in {pow(7,e,10)} and {pow(3,e+1,10)}.',f'Add these last digits and keep only the units digit: {ans}.'],'Reduce each power separately; the two cycles start differently.','Two repeating cycles can be combined after each is indexed correctly.')
    if k=='FRAC-01':
        if role=='try':return task(f'A water bottle holds {12*x} mL. A third is drunk, then a quarter of what remains is drunk. How many mL remain?',6*x,[f'After the first drink, two thirds remain: {8*x} mL.',f'Keep three quarters of that: {6*x} mL.'],'The second fraction refers to the smaller remaining amount.','Successive fractions can refer to different wholes.')
        return task(f'A seed store sends half its seeds to one garden, then a third of the remaining seeds to another. It has {3*x} seeds left. How many seeds did it start with?',9*x,[f'The final {3*x} is two thirds of the amount after the first shipment; that amount was {Fraction(9*x,2)}.',f'Double that intermediate amount to recover the start: {9*x}.'],'If the first half is not a whole number of seeds, this setup is invalid — use the adjusted even parameter supplied by the generator.','Name each whole and work backwards through the fractions.')
    if k=='FRAC-02':
        if role=='try':return task(f'A mix has oats and seeds in the ratio 5:3. It contains {2*x} grams more oats than seeds. How many grams of mix are there?',8*x,[f'The difference is 2 parts, so one part is {x} grams.',f'The whole is 8 parts: {8*x} grams.'],'The oats and seeds must differ by the given amount.','A difference, rather than a total, sets the size of one ratio part.')
        return task(f'A paint mix has blue and white in the ratio 2:5. There are {2*x} mL of blue. Only blue is added until the ratio is 1:1. How many mL of blue must be added?',3*x,[f'One original part is {x}; white stays at {5*x} mL.',f'Blue must also become {5*x}; add {5*x}−{2*x}={3*x}.'],'The unchanged white amount anchors the new ratio.','When a ratio changes, identify the quantity that stayed fixed.')
    if k=='FRAC-03':
        if role=='try':return task(f'A kit costs ${20*x}. It is discounted by 25%, then a $7 delivery charge is added. What is the total in dollars?',15*x+7,[f'The discount leaves 75% of {20*x}, which is {15*x}.',f'Delivery is a separate fixed amount: {15*x}+7={15*x+7}.'],'Do not discount a charge that was added afterwards.','Percentages act on a named base, while fixed charges are separate.')
        return task(f'A club grows from {8*x} members to {10*x}. By what percentage of the new membership must it shrink to return to its original size?',20,[f'The decrease needed is {2*x} out of the new {10*x}.',f'{2*x}/{10*x} = 1/5 = 20%.'],'The growth was 25% of the old total, but the reversal uses the larger new total.','Reverse percentage changes use a different base.')
    if k=='FRAC-04':
        if role=='try':return task(f'In one group of {6*x} children, a third cycle to school. In another group of {4*x}, half cycle. How many children in the combined groups do NOT cycle?',6*x,[f'Cyclists: {2*x}+{2*x}={4*x}. Total children: {10*x}.',f'Non-cyclists: {10*x}−{4*x}={6*x}.'],'Use counts before combining; averaging the fractions would weight the groups equally.','Different group sizes require separate fraction-to-count calculations.')
        return task(f'A crate has {3*x} glass bottles, of which a third are empty, and {2*x} metal bottles, of which a half are empty. What fraction of all the bottles are full?', '3/5',[f'Empty bottles: {x}+{x}={2*x} out of {5*x}.',f'Full bottles: {3*x}; the fraction is {3*x}/{5*x}=3/5.'],'The denominator is all bottles, not just one material.','Recover the whole and combine counts before forming the final fraction.')
    if k=='RATE-01':
        if role=='try':return task(f'A train passes {x+1} evenly spaced posts in 18 seconds from the first post to the last. The posts are 6 metres apart. What is its speed in metres per second? Give an exact fraction if needed.',str(Fraction(x,3)),[f'{x+1} posts create {x} gaps, a distance of {6*x} metres.',f'Divide distance by 18 seconds: {Fraction(x,3)} m/s.'],'Using the number of posts as the number of gaps adds one imaginary interval.','The times refer to endpoints, so count intervals before using a rate.')
        return task(f'A robot records a reading immediately on starting, then every 8 seconds. Its {ordinal(x+2)} reading is the final reading. How many seconds later must another robot start if it takes only {x} readings at the same interval and must finish at exactly the same time?',16,[f'The first robot runs for {x+1} gaps; the second for {x-1} gaps.', 'The difference is two gaps of 8 seconds, so delay the second start by 16 seconds.'],'Both timelines finish at the same instant; the first reading takes no waiting interval.','Compare two sets of endpoint-inclusive events.')
    if k=='RATE-02':
        if role=='try':return task(f'A pump fills an empty tank in {6*x} minutes. A leak empties a full tank in {12*x} minutes. With both running at constant rates, how many minutes fill an empty tank?',12*x,[f'In {12*x} minutes the pump adds two tankfuls and the leak removes one.',f'The net rate is one tank per {12*x} minutes.'],'The leak slows filling, so the result must exceed the pump-only time.','Opposing rates subtract; times do not.')
        return task(f'Two machines together make {6*x} pieces an hour. The first alone makes {2*x} pieces an hour. How many hours does the second alone need to make {12*x} pieces?',3,[f'The second rate is {6*x}−{2*x}={4*x} pieces per hour.',f'Time = {12*x} ÷ {4*x}=3 hours.'],'The individual rates add to the stated combined rate.','Recover the missing rate before finding time.')
    if k=='RATE-03':
        if role=='try':return task(f'A rover travels for 15 minutes at {4*x} km/h, stops for 10 minutes, then travels for 30 minutes at {2*x} km/h. How far does it travel in kilometres?',2*x,[f'First distance: one quarter of {4*x} = {x} km. Second: one half of {2*x} = {x} km.',f'The stop adds time but no distance. Total {2*x} km.'],'Do not apply a speed to the stopped interval.','Split a journey where speed changes and convert each time to hours.')
        return task(f'A walker covers {2*x} km at {x} km/h and returns over the same route at {2*x} km/h. What is the average speed for the whole trip in km/h? Give an exact fraction.',str(Fraction(4*x,3)),['The outward trip takes 2 hours and the return takes 1 hour.',f'Total distance {4*x} divided by total time 3 gives {Fraction(4*x,3)} km/h.'],'The slower speed lasts longer, so the ordinary average of the two speeds is wrong.','Average speed means total distance divided by total time.')
    if k=='RATE-04':
        if role=='try':return task(f'Two robots move in the same direction. The front robot is {3*x} metres ahead and moves at 2 m/s. The rear robot moves at 5 m/s. How many seconds until it catches up?',x,['The gap closes at 5−2=3 metres per second.',f'Divide the gap {3*x} by 3 to get {x} seconds.'],'Both positions agree at that time when measured from the rear starting point.','Same-direction catching uses the difference of speeds.')
        return task(f'Two runners start together on a {6*x}-metre circular track and run in opposite directions at 2 m/s and 4 m/s. After how many seconds do they meet for the third time after starting?',3*x,[f'They close one track length every {6*x}/(2+4)={x} seconds.',f'The third meeting after the start is at {3*x} seconds.'],'The starting instant is not counted as a meeting after starting.','Opposite directions close the gap at the sum of speeds; then count repeat events.')
    if k=='ALG-01':
        if role=='try':return task(f'A workshop charges $9 entry plus $4 per model built. A visitor pays ${9+4*x}. How many models did the visitor build?',x,[f'Remove the fixed entry charge: {9+4*x}−9={4*x}.',f'Divide by the $4 per model: {x}.'],'Substitute into total = entry + number × cost.','Separate a fixed amount from a repeated amount.')
        return task(f'A museum sells adult tickets for $9 and child tickets for $5. A group buys {x+4} tickets for ${5*(x+4)+12}. How many adult tickets are there?',3,[f'If every ticket were a child ticket, the cost would be {5*(x+4)}.', 'Each adult instead of a child adds $4. The extra $12 therefore means 3 adults.'],'Three adults and the remaining children must give both the correct count and total cost.','Choose a simple baseline; the difference reveals the unknown mix.')
    if k=='ALG-02':
        if role=='try':return task(f'A parcel and its box weigh {3*x+8} kg altogether. The parcel weighs {x+2} kg more than the box. How heavy is the parcel in kg?',2*x+5,[f'Remove the difference from the total and halve to find the box: {x+3} kg.',f'Add the difference back to find the parcel: {2*x+5} kg.'],'The two weights must add to the total and have the stated difference.','The total and gap identify two unknown quantities.')
        return task(f'Two ropes together measure {6*x} cm. If 8 cm is cut from the longer one, it is {2*x-8} cm longer than the other. How long was the shorter rope in cm?',2*x,[f'Before cutting, the difference was ({2*x-8})+8={2*x}.',f'The shorter length is ({6*x}−{2*x})/2={2*x}.'],'Apply the cut afterwards and check the new difference.','First recover the original difference, then use the original total.')
    if k=='ALG-03':
        if role=='try':return task(f'Two identical toolboxes and three lamps cost ${2*(x+5)+3*x}. Two of the same toolboxes and five lamps cost ${2*(x+5)+5*x}. What does one lamp cost in dollars?',x,['Subtract the purchases; the two toolboxes cancel.',f'Two extra lamps cost {2*x}, so one costs {x}.'],'Replacing the lamp cost in both purchases gives the same toolbox cost.','An equal unknown part appears in two totals and can be cancelled.')
        return task(f'Three jars and two mugs cost ${3*x+2*(x+4)}. Six jars and five mugs cost ${6*x+5*(x+4)}. What does a mug cost in dollars?',x+4,[f'Double the first purchase: six jars and four mugs cost {2*(3*x+2*(x+4))}.',f'Subtract it from the second purchase; one mug remains, costing {x+4}.'],'The recovered jar and mug prices satisfy both original equations.','Equalise one contribution before subtracting; direct subtraction would leave two unknowns.')
    if k=='ALG-04':
        if role=='try':return task(f'A number machine multiplies its input by 3, adds 8 and then divides the result by 2. The final output is {3*x+4}. What number was entered at the start?',2*x,[f'Undo the final halving by doubling: {6*x+8}.',f'Subtract 8, then divide by 3: {2*x}.'],'Run the original three operations forwards to verify the display.','An operation chain gives the end; undo operations in reverse order.')
        return task(f'A student starts with some pocket money. They spend $6, then spend half of the money that remains. Later, they receive another $5 and end up with ${x+5}. How many dollars did they have at the start?',2*x+6,[f'Undo the final gift: {x}. Undo spending half by doubling: {2*x}.',f'Undo the initial $6 spend by adding 6: {2*x+6}.'],'A forward check keeps the fixed payment, fractional spend and gift in their proper order.','Undo a story one action at a time, using the right intermediate whole.')
    if k=='ALG-05':
        if role=='try':return task(f'One container has {5*x} beads and another has {3*x}. How many beads must move from the first to the second so that the second has {x} more than the first?',str(Fraction(3*x,2)),[f'The gap must change from {2*x} in favour of the first to {x} in favour of the second: a change of {3*x}.',f'Each transfer changes the gap by 2, so transfer {Fraction(3*x,2)}.'],'Use the even parameter selected for discrete beads, and check both final counts.','A transfer changes both quantities; it changes the gap by twice the transfer.')
        return task(f'Two reservoirs contain {7*x} and {3*x} litres. After water is transferred from the first to the second, the first contains twice as much as the second. How many litres were transferred? Give an exact fraction if needed.',str(Fraction(x,3)),[f'The total stays {10*x}. A final 2:1 ratio makes the second reservoir {Fraction(10*x,3)} litres.',f'Subtract its original {3*x}: transfer {Fraction(x,3)} litres.'],'The two final amounts sum to the original total and meet the new ratio.','Combine an unchanged total with a final ratio instead of assuming equal amounts.')
    if k=='SEQ-01':
        if role=='try':return task(f'A display has {x} lights in its first row and 3 more in each next row. How many lights are in its first 8 rows altogether?',8*x+84,[f'The eighth row has {x+21}; pair first with last, second with seventh, and so on.',f'Four equal pairs total 4 × ({x}+{x+21})={8*x+84}.'],'The average row size times eight agrees with the paired sum.','Equal increments suggest an arithmetic sequence; the question asks for a sum.')
        return task(f'A ramp pattern uses {x} blocks in stage 1 and 4 extra blocks for each later stage. Which stage uses {x+4*(n+3)} blocks?',n+4,[f'The increase from stage 1 is {4*(n+3)}, requiring {n+3} increments.',f'The stage number is one more: {n+4}.'],'Substitute the stage into first amount + (stage−1) × 4.','Solve backwards for the number of increments, keeping stage 1 separate.')
    if k=='SEQ-02':
        if role=='try':return task(f'A lab starts with {x} cells. The population doubles at the end of each hour. How many cells are present at the end of hour 5?',32*x,[f'Five completed doublings multiply the starting population by 2⁵=32.',f'{x} × 32 = {32*x}.'],'At hour zero there are already the starting cells; there are five transitions.','A repeated multiplier gives geometric growth, with an explicit starting time.')
        return task(f'A game pays {x} points for round 1 and twice the previous round for each later round. What is the smallest number of rounds whose total points exceed {x*(2**(n%4+3)-1)}?',n%4+4,[f'After k rounds the total is {x} × (2^k−1).',f'At {n%4+3} rounds it is exactly the stated threshold. The next round is needed for strictly more: {n%4+4}.'],'Do not confuse the final round payment with the total, or equal to with greater than.','A geometric total must be compared with a strict threshold.')
    if k=='SEQ-03':
        f=[1,1]
        for i in range(2,20):f.append(f[-1]+f[-2])
        L=n+2
        if role=='try':return task(f'A signal is a row of {L} lamps, each on or off. Two on lamps may not be adjacent. How many different signals are possible, including all lamps off?',f[L+1],[f'Split by the last lamp: off leaves a valid length-{L-1} signal; on forces the previous lamp off and leaves length {L-2}.',f'Starting with counts 1 for length 0 and 2 for length 1, the total for length {L} is {f[L+1]}.'],'The two cases have different final lamps, so they cannot overlap.','The last choice reduces the problem to smaller copies of itself.')
        vals=[1,1,1]
        for i in range(3,L+1):vals.append(vals[-1]+vals[-3])
        return task(f'A path of length {L} metres is crossed using only jumps of 1 metre or 3 metres, landing exactly at the end. How many different ordered jump sequences work?',vals[L],['Split by the last jump: 1 metre leaves length k−1; 3 metres leaves length k−3.',f'Counts from length zero onward are {", ".join(map(str,vals))}. The required count is {vals[L]}.'],'Use an empty sequence for length zero; the recurrence here is not the one-or-two-step recurrence.','The allowed final moves determine which earlier counts are added.')
    if k=='SEQ-04':
        t=6*n+5
        if role=='try':return task(f'A robot repeats the moves Right, Right, Up, Left in that order. Starting at (0,0), what is its horizontal coordinate after {t} moves?',t//4+[0,1,2,2][t%4],[f'Each full four-move block changes the horizontal coordinate by +1. There are {t//4} full blocks.',f'The remaining {t%4} moves add {[0,1,2,2][t%4]}, giving {t//4+[0,1,2,2][t%4]}.'],'A repeating instruction cycle can still produce a changing position.','Track both the cycle position and the accumulated displacement.')
        t=12*n+7;val=(t%3)+1
        return task(f'A display cycles 1, 2, 3, 1, 2, 3, … starting at 1 at time 0. A lamp toggles blue/gold each second, starting blue. At time {t} seconds, what number is shown?',val,['The number repeats every 3 seconds; the lamp repeats every 2.',f'The combined state repeats every lcm(3,2)=6 seconds. {t} leaves remainder {t%6}, so the number is {val}.'],'A match in the number alone does not prove the full state has repeated.','A complete state includes every changing component.')
    if k=='COUNT-01':
        total=2*n+9;vals=[(a,b) for a in range(1,total) for b in range(a+1,total) if a+b==total and a%2==1]
        if role=='try':return task(f'Two different positive whole numbers add to {total}. The smaller one must be odd. How many pairs are possible if order does not matter?',len(vals),[f'The smaller number is below {total}/2; list just the odd candidates.',f'Each fixes its partner. The pairs are {vals}, so there are {len(vals)}.'],'Listing only the smaller member prevents reversed duplicates.','Organise the cases with a unique representative for each pair.')
        total=n+12;vals=[(a,b,c) for a in range(1,total) for b in range(a,total) for c in range(b,total) if a+b+c==total and c-a<=3]
        return task(f'Three positive whole-number lengths add to {total}. Their largest and smallest differ by at most 3. How many triples are possible, ignoring order?',len(vals),['Write the lengths a ≤ b ≤ c. Try the smallest length, then b, with c determined by the total.',f'Keep only c ≥ b and c−a ≤ 3. The complete list is {vals}; count {len(vals)}.'],'Recover each triple from its sorted order; there are no permutations to count again.','An ordering convention makes an exhaustive list manageable.')
    if k=='COUNT-02':
        if role=='try':return task(f'From {x} pupils, a captain and a different deputy are chosen. A two-person support team is then chosen from the remaining pupils, with no roles inside that team. How many selections are possible?',x*(x-1)*C(x-2,2),[f'The two named roles have {x} × {x-1} choices.',f'The support pair has C({x-2},2)={C(x-2,2)} choices. Multiply to get {x*(x-1)*C(x-2,2)}.'],'Swap captain and deputy and the selection changes; swapping support members does not.','Some choices have roles while others are unordered.')
        return task(f'A menu has {x} savoury dishes and 3 desserts. A meal chooses two different savoury dishes with no serving order, and one dessert. How many meals are possible?',3*C(x,2),[f'The savoury pair has {x}×{x-1}/2={C(x,2)} choices.',f'Each pair can take any of 3 desserts, giving {3*C(x,2)} meals.'],'Pair order is ignored, but dessert choice still creates a new meal.','Multiply independent choices after removing duplicate orderings.')
    if k=='COUNT-03':
        L=n%3+5
        if role=='try':
            fixed=min(2,(n-3)//3);free=L-fixed;v=math.factorial(free)-2*math.factorial(free-1)
            condition='' if fixed==0 else ' Magnet C is fixed at the first position.' if fixed==1 else ' Magnet C is fixed first and magnet D is fixed last.'
            return task(f'{L} different magnets are arranged in a row. Magnets A and B must NOT be neighbours.{condition} How many arrangements are allowed?',v,[f'After fixing any specified ends, there are {free} free magnets in a consecutive set of positions: {free}!={math.factorial(free)} orders.',f'Forbidden A/B neighbours form a block with two internal orders: 2×{free-1}!={2*math.factorial(free-1)}. Subtract to get {v}.'],'Every forbidden row contains the unique A/B block. Fixed ends are not among A and B.','First apply fixed-position restrictions, then subtract the forbidden adjacent cases.')
        L=n+2;val=C(L-1,2)
        return task(f'A row contains {L} numbered positions. Two identical sensors must occupy positions that are not adjacent. How many choices of positions are possible?',val,[f'All pairs of positions: C({L},2)={C(L,2)}.',f'Exactly {L-1} pairs are adjacent. Subtract: {C(L,2)}−{L-1}={val}.'],'List adjacent gaps rather than subtracting once for every occupied position.','Count all pairs and remove the precisely described forbidden pairs.')
    if k=='COUNT-04':
        if role=='try':return task(f'Of {6*x} visitors, {3*x} see a robot display, {2*x} see a telescope display, and {x} see both. How many see neither?',2*x,[f'At least one display: {3*x}+{2*x}−{x}={4*x}.',f'Neither: {6*x}−{4*x}={2*x}.'],'Partition into robot only, telescope only, both and neither; the counts sum to all visitors.','Correct the overlap before taking a complement.')
        return task(f'How many whole numbers from 1 through {6*x}, inclusive, are divisible by 2 or 3 but NOT both?',3*x,[f'Multiples of 2: {3*x}; of 3: {2*x}; of both: {x}.',f'The overlap must be removed twice: {3*x}+{2*x}−2×{x}={3*x}.'],'Both is excluded entirely, whereas an ordinary union would keep it once.','The words “but not both” change how the overlap is handled.')
    if k=='COUNT-05':
        if role=='try':return task(f'Each of {2*x} stations connects directly to exactly 3 other stations. Every link joins two stations. How many links are there?',3*x,[f'Station reports count {2*x}×3={6*x} link endpoints.',f'Each link has two endpoints, so divide by two: {3*x}.'],'Twice the link count equals the total reported degree.','Count incidences, then account for how many reports belong to one object.')
        return task(f'A club has {3*x} people. Each joins exactly 2 workshops. Every workshop has exactly 6 people. How many workshops are there?',x,[f'Count person-workshop memberships from the people: {3*x}×2={6*x}.',f'Each workshop contributes 6 memberships, so there are {x} workshops.'],'Counting from workshops gives 6 times the answer, the same membership total.','The same memberships can be counted from people or from groups.')
    if k=='COUNT-06':
        d=n%5+4
        if role=='try':
            val=sum((a==1)+(b==1)==1 for a in range(1,d+1) for b in range(1,d+1))
            return task(f'Two positions each contain a digit from 1 to {d}. Repetition is allowed, but exactly one position must contain 1. How many codes are possible?',val,[f'If the first position is 1 there are {d-1} choices for the second.',f'If the second is 1 there are {d-1} choices for the first. The cases are disjoint: {val}.'],'The code 11 is forbidden by “exactly one”.','Split by which position supplies the required feature.')
        val=3*(d-1)**2
        return task(f'A three-character code uses digits 1 to {d}, with repeats allowed. Exactly one character is 2. How many codes are possible?',val,['Choose the unique position containing 2: 3 choices.',f'The other two positions each have {d-1} choices. Total 3×{d-1}²={val}.'],'Every valid code has one unique position for the 2, so no case overlaps.','Classify by the position of a unique special element, then count freely inside each case.')
    if k=='LOGIC-01':
        if role=='try':
            return task(f'Two robots always tell the truth or always lie. Ada says “We are both liars.” Ben says “The access code is {x}.” What is the access code?',x,['Ada cannot be truthful: her sentence would say that Ada lies. Thus Ada is a liar.',f'Her sentence is false, so they are not both liars. Ben is truthful; the code is {x}.'],'Check that Ada’s statement is false and Ben’s true under the assigned types.','Assume each truth type and check the meaning of the whole statement.')
        return task(f'A key is in exactly one of boxes {x}, {x+1} and {x+2}. The labels say: box {x}: “The key is not here”; box {x+1}: “The key is in box {x}”; box {x+2}: “The key is not in box {x+1}”. Exactly one label is true. Which box contains the key?',x+1,[f'Test each key location. If it is in box {x}, the last two labels are true. If it is in box {x+2}, the first and last labels are true.', f'Only box {x+1} makes exactly one label true (the first label).'],'Check all three labels for the surviving location, rather than assuming a label describes its own box truthfully.','Count true statements for each possible underlying situation.')
    if k=='LOGIC-02':
        total=3*x+3
        if role=='try':return task(f'Three consecutive whole numbers total {total}. The middle number labels a locker. What is the locker number?',x+1,[f'Write the numbers as middle−1, middle, middle+1.',f'The offsets cancel, leaving 3×middle={total}; middle={x+1}.'],'The three reconstructed numbers are consecutive and have the stated sum.','Use the strongest relationship to represent all unknowns with one quantity.')
        vals=[i for i in range(1,100) if i%4==1 and i%7==n%7 and 20+n<i<60+n]
        # Add a bound derived from a unique surviving value, with no guessing of uniqueness.
        v=vals[0] if vals else next(i for i in range(20,150) if i%4==1 and i%7==n%7)
        return task(f'A whole number is greater than {v-9} and less than {v+12}. It leaves remainder 1 on division by 4 and remainder {n%7} on division by 7. What is it?',v,['List the numbers in the interval with remainder 1 on division by 4.',f'Test their remainders on division by 7; only {v} survives.'],'Two solutions to both remainder conditions would differ by a multiple of 28, larger than this interval.','Intersect restrictions and prove no second candidate remains.')
    if k=='LOGIC-03':
        if role=='try':return task(f'A 3-by-3 table contains numbers. Its row totals are {x+5}, {2*x+3} and {x+8}. Two column totals are {x+4} and {x+9}. What is the remaining column total?',2*x+3,[f'The grand total from the rows is {4*x+16}.',f'Subtract the two known columns: {4*x+16}−{x+4}−{x+9}={2*x+3}.'],'The sum of all column totals must equal the sum of all row totals.','Different groupings count exactly the same entries.')
        return task(f'A table has four rows. Their totals add to {10*x}. Three column totals add to {7*x}; the fourth column total is not shown. An entry in that fourth column is then increased by 6. What is the new fourth-column total?',3*x+6,[f'Before the change, the fourth column totals {10*x}−{7*x}={3*x}.',f'Only its changed entry adds 6, so the new total is {3*x+6}.'],'The new grand total also increases by 6; the other column totals stay fixed.','Use a conserved grand total, then account for the one change.')
    if k=='LOGIC-04':
        a=n%4+2;b=a+3
        if role=='try':return task(f'Two positive whole numbers have product {a*b} and differ by 3. What is the smaller one?',a,[f'List all factor pairs of {a*b}.',f'Only ({a},{b}) has difference 3, so the smaller is {a}.'],'Check every factor pair to establish uniqueness, not just that one pair works.','A complete factor-pair list can turn an example into a uniqueness proof.')
        total=2*x;v=x-2
        return task(f'Two different even positive whole numbers total {total}. What is the largest possible value of the smaller number?',x-2 if x%2==0 else x-1,[f'The smaller number is strictly below half of {total}, namely {x}.',f'Take the largest even integer below {x}: {x-2 if x%2==0 else x-1}. Its partner is even, larger, and has the required total.'],'The strict upper bound excludes every larger candidate and the constructed pair attains the answer.','Prove a bound, then show a legal example reaches it.')
    if k=='GEO-01':
        if role=='try':return task(f'Two rectangles, {x} cm by 4 cm and {x+2} cm by 4 cm, join along one complete 4-cm side with no overlap. What is the outside perimeter in cm?',4*x+12,[f'The separate perimeters sum to {4*x+20}.',f'The shared 4-cm side is counted twice but is internal. Subtract 8 to get {4*x+12}.'],f'The joined shape is a rectangle of width {2*x+2} cm and height 4 cm; its perimeter is 2 × ({2*x+2} + 4) = {4*x+12} cm.','Joined shapes lose two copies of a shared boundary.')
        return task(f'A {x+6}-cm by {x+2}-cm rectangular card has a 2-cm by 3-cm rectangular notch cut inward from the middle of a long side. The opening along that side is 2 cm and the depth is 3 cm. What is the new perimeter in cm?',4*x+22,[f'The old perimeter is {4*x+16}. The 2-cm opening is replaced by another 2-cm edge plus two 3-cm edges.',f'The net increase is 6 cm; new perimeter {4*x+22}.'],'The removed area does not directly tell you the boundary change.','Trace deleted and newly exposed edges instead of counting area.')
    if k=='GEO-02':
        if role=='try':return task(f'A rectangle is {2*x} cm wide and 9 cm high. A triangle uses the entire bottom side as its base and its third vertex anywhere on the top side. What area of the rectangle lies outside the triangle, in square cm?',9*x,[f'The triangle has base {2*x} and perpendicular height 9, regardless of where the top vertex sits.',f'It takes half the rectangle. The remaining area is {9*x} cm².'],'Sliding the vertex along a parallel line changes the slant sides but not the height.','Look for a fixed base and perpendicular height.')
        return task(f'A triangular flag has area {6*x} cm² and base {2*x} cm. A second triangle shares that same base but has half the first height. What is the area between the two triangles if the smaller lies inside the larger?',3*x,[f'With a common base, halving the height halves the area: the smaller area is {3*x}.',f'Subtract it from the larger: {6*x}−{3*x}={3*x} cm².'],'Use perpendicular height; no slant length is needed.','Compare areas through a shared base, then take the complement.')
    if k=='GEO-03':
        a=30+n
        if role=='try':return task(f'A triangle has two equal angles. Its third angle is {2*a}°. What is one of the equal angles in degrees?',90-a,[f'The two equal angles total 180−{2*a}={180-2*a}°.',f'Halve that total: {90-a}°.'],'All three angles must sum to 180°.','Equality plus a fixed angle total gives an equation.')
        return task(f'One side of a triangle is extended at a vertex. The exterior angle there is {110+n}°. One of the two non-adjacent interior angles is {35+n}°. What is the other non-adjacent interior angle in degrees?',75,[f'The interior angle beside the exterior is 180−{110+n}={70-n}°.',f'The remaining angle is 180−{70-n}−{35+n}=75°.'],'Equivalently, the exterior angle equals the two non-adjacent interior angles added together.','Connect a straight-line angle to the triangle angle sum.')
    if k=='GEO-04':
        if role=='try':return task(f'A regular {2*x}-sided polygon has vertices alternately marked blue and gold. How many rotations less than 360°, including zero, preserve both its outline and every vertex colour?',x,[f'An outline-preserving turn moves each vertex an integer number of positions.',f'Colours match only after an even number of positions. Half of {2*x} rotations work: {x}.'],'A one-position turn preserves the shape but swaps the colours, so it is not allowed.','A symmetry must preserve all marked features, not just the outline.')
        return task(f'A regular {2*x}-sided polygon has two adjacent vertices marked red and all other vertices marked blue. How many reflection axes preserve both the polygon and the colours?',1,['A valid reflection must preserve the unique red edge joining the two adjacent red vertices.', 'Only its perpendicular bisector does so: it swaps the two red endpoints and preserves all blue vertices. There is 1 axis.'],'Every other reflection sends at least one endpoint of the red edge to a blue vertex.','A uniquely marked feature constrains all possible symmetries.')
    if k=='GEO-05':
        if role=='try':return task(f'A rectangular pen is built against a straight wall. Only the other three sides need fencing. There are {4*x} metres of fence. Side lengths must be positive whole numbers. What is the largest possible area in square metres?',2*x*x,[f'If the two equal widths are w, the fenced length is {4*x}−2w. The area is w({4*x}−2w).',f'Writing w={x}+d gives area {2*x*x}−2d², at most {2*x*x}. Choose width {x}, length {2*x}.'],'The construction uses exactly the available three-sided fencing.','A bound must reflect which sides use the limited resource.')
        return task(f'A rectangular array has {4*x*x-1} squares. Both side lengths are positive whole numbers. What is the smallest possible perimeter in unit lengths?',8*x,[f'{4*x*x-1}=({2*x}-1)({2*x}+1). These adjacent odd factors give perimeter {8*x}.',f'If the side sum were at most {4*x-1}, its largest possible integer product would be {2*x-1}×{2*x}, below {4*x*x-1}. So a smaller perimeter is impossible.'],'The pair 2x−1 and 2x+1 meets the area exactly and attains the lower bound.','Find a construction and a lower bound; do not assume every area can form a square.')
    if k=='SOLID-01':
        if role=='try':return task(f'A solid model has a bottom layer {x} cubes by 5 cubes, a second layer {x-1} by 4, and a top layer {x-2} by 3. How many unit cubes does it contain?',12*x-10,[f'The layers contain {5*x}, {4*(x-1)}, and {3*(x-2)} cubes.',f'Add all layers, including hidden cubes: {12*x-10}.'],'Do not count just the visible faces in a perspective drawing.','A layered description lets you count concealed cubes without a picture.')
        return task(f'A solid block measures {x} by 6 by 4 unit cubes. A straight 1-by-2 tunnel is cut all the way through its {x}-cube length. The tunnel lies inside the other two dimensions. How many cubes remain?',22*x,[f'The full block has {24*x} cubes.',f'The tunnel removes 1×2×{x}={2*x} cubes. Remainder {22*x}.'],f'Each of the {x} lengthwise cross-sections loses 2 cubes, so the tunnel removes {2*x} cubes altogether.','Describe the removed volume by its cross-section and length.')
    if k=='SOLID-02':
        a=n+2;b=a+1;c=a+2
        if role=='try':return task(f'An {a}-by-{b}-by-{c} block of unit cubes is painted on all outer faces. How many unit cubes have exactly two painted faces?',4*(a+b+c-6),['Exactly two painted faces means an edge cube that is not a corner.',f'There are four edges of each length. Count 4×[({a}−2)+({b}−2)+({c}−2)]={4*(a+b+c-6)}.'],'Corners have three painted faces and must be excluded from each edge.','Classify cubes by how many exterior boundaries meet at them.')
        return task(f'A solid block is {a} cubes wide, {b} cubes deep and {c} cubes high. It is painted only on its top and bottom faces. How many cubes have exactly one painted face?',2*a*b,[f'Top and bottom layers each contain {a*b} cubes.',f'Because the height is {c}>1, these layers are disjoint. Total {2*a*b}.'],'The unpainted side faces contribute nothing to the painted-face count.','The painting instructions, not just the shape, determine the cases.')
    if k=='SOLID-03':
        if role=='try':return task(f'An open-topped rectangular box has base {x} cm by 4 cm and height 3 cm. What is the area of material in its base and four sides, in square cm? Ignore thickness.',10*x+24,[f'Base: {4*x}. Two long sides: {6*x}. Two short sides: 24.',f'Total {4*x}+{6*x}+24={10*x+24} cm².'],'There is no lid; counting two bases would add an unwanted face.','Inventory the actual faces before applying a surface-area formula.')
        return task(f'A solid cube of side {x} cm is cut once into two equal cuboids by a plane parallel to a face. What is the total surface area of both pieces, in square cm?',8*x*x,[f'The six original faces contribute {6*x*x}.',f'The cut exposes two new square faces, each {x*x}. Total {8*x*x}.'],'The volume is unchanged, but the new surfaces add area.','A cut creates two exposed faces that were previously internal.')
    if k=='SPATIAL-01':
        a=n%4+3
        if role=='try':return task(f'A robot travels from (0,0) to ({a},2) using only Right and Up unit moves. It must pass through (1,1). How many routes work?',2*C(a,1),['To (1,1) there are 2 orders of the two moves.',f'From (1,1) to ({a},2), choose the one remaining Up position among {a} moves: {a}. Multiply to get {2*a}.'],'Every route has one unique before-waypoint part and one after-waypoint part.','A compulsory waypoint splits a route into independent sections.')
        return task(f'A robot travels from (0,0) to ({a},2) with Right and Up unit moves, but (1,1) is blocked. How many routes remain?',C(a+2,2)-2*a,[f'All routes: C({a+2},2)={C(a+2,2)}.',f'Routes through the blocked point: 2×{a}={2*a}. Subtract to get {C(a+2,2)-2*a}.'],'Subtract entire routes through the point, not just the point itself.','A forbidden waypoint suggests subtracting bad routes from all routes.')
    if k=='SPATIAL-02':
        if role=='try':return task(f'A rectangular grid has {x} vertical lines and 4 horizontal lines. How many rectangles use the leftmost vertical line as one side?',6*(x-1),[f'The other vertical boundary has {x-1} choices.',f'The two horizontal boundaries have C(4,2)=6 choices. Multiply: {6*(x-1)}.'],'No rectangle is counted twice because its left boundary is fixed.','Choose boundaries, with any compulsory boundary handled first.')
        return task(f'A grid has {x} vertical lines and 4 horizontal lines. One new vertical line is added inside the grid. How many NEW rectangles become possible?',6*x,[f'Every new rectangle must use the new line and exactly one of the {x} old vertical lines.',f'Choose two of the four horizontal lines in 6 ways. Total {6*x}.'],'The difference between the total rectangle counts before and after gives the same result.','Count only the objects containing the newly introduced feature.')
    if k=='SPATIAL-03':
        if role=='try':return task(f'A board has 2 rows and {2*x+1} columns. One corner square is removed. Can the remaining board be tiled by dominoes covering 2 squares each? Answer yes or no.','no',[f'The full board has {4*x+2} squares, so the remainder has {4*x+1}, an odd number.', 'Every domino covers an even number of squares. An odd area cannot be tiled.'],'A simple area parity obstruction is sufficient here; a more complicated colouring is unnecessary.','Find a quantity every tile contributes in fixed multiples.')
        return task(f'A board has 2 rows and {2*x} columns, coloured like a chessboard. Remove the top-left square and the bottom-right square. Can dominoes tile the remainder? Answer yes or no.','no',['These two removed squares have the same checkerboard colour, because both row and column parity change.', 'Every domino covers one of each colour, but the remaining colour counts differ by two. Therefore no tiling exists.'],'An even number of remaining squares is necessary but not sufficient.','When area parity passes, a colour balance can reveal a stronger invariant.')
    if k=='SPATIAL-04':
        if role=='try':return task(f'A connected network is a ring of {x} vertices with one extra edge connecting two vertices that were not neighbours. Can a single trail use each edge exactly once, with different starting and finishing vertices? Answer yes or no.','yes',['Every ring vertex has degree 2. The extra edge makes its two endpoints degree 3.', 'Exactly two vertices are odd, so an Euler trail exists between them in this connected graph.'],'For a closed trail all degrees would need to be even; this one is allowed to start and finish differently.','Count odd-degree vertices and distinguish a trail from a closed trail.')
        return task(f'A cycle with {x} edges and a cycle with {x+1} edges share exactly one vertex. No other vertices or edges are shared. Can one closed trail use every edge exactly once? Answer yes or no.','yes',['The shared vertex has degree 4; all other vertices have degree 2.', 'The graph is connected and all degrees are even. Trace one cycle back to the shared vertex, then the other.'],'The explicit route verifies the degree test and shows no edge is repeated.','A closed edge-by-edge trail requires connectedness and even degrees.')
    if k=='DATA-01':
        if role=='try':return task(f'A bag holds {x} blue tokens and 3 gold tokens. Two tokens are drawn without replacement. What is the probability both are gold? Give an exact fraction.',str(Fraction(6,(x+3)*(x+2))),[f'The first gold probability is 3/{x+3}. Afterwards there are 2 gold among {x+2} tokens.',f'Multiply to get {Fraction(6,(x+3)*(x+2))}.'],'The second denominator is smaller because the first token is not replaced.','Track how a choice changes the remaining sample space.')
        return task(f'A number is chosen uniformly from 1 through {6*x}. You are told it is divisible by 3. What is the probability it is also even? Give an exact fraction.','1/2',[f'The given information restricts the possibilities to {2*x} multiples of 3.',f'Exactly {x} are multiples of 6 and hence even. Probability {x}/{2*x}=1/2.'],'Use the restricted sample space, not all the original numbers.','New information changes the denominator of a probability.')
    if k=='DATA-02':
        if role=='try':return task(f'A team of {x} pupils has mean score 12. A second team of 3 pupils has mean score 20. What is the combined mean? Give an exact fraction.',str(Fraction(12*x+60,x+3)),[f'Recover the totals: {12*x} and 60.',f'Divide their sum by {x+3} pupils: {Fraction(12*x+60,x+3)}.'],'A plain average of 12 and 20 would incorrectly give both teams equal weight.','Means combine through totals and group sizes.')
        return task(f'The mean of {x} measurements is 14. One measurement, recorded as 19, should have been 9. What is the corrected mean? Give an exact fraction.',str(Fraction(14*x-10,x)),[f'The original total was {14*x}. The correction lowers it by 10.',f'The count stays {x}. The new mean is {Fraction(14*x-10,x)}.'],'The mean decreases by 10 divided by the count, not by 10 itself.','Correct the total while keeping track of whether the number of entries changes.')
    if k=='DATA-03':
        if role=='try':return task(f'A chart counts repaired bikes. Monday: {x} full symbols and one half-symbol. Tuesday: {x+2} full symbols. Each full symbol represents 6 bikes. How many more bikes were repaired on Tuesday?',9,[f'Monday represents {6*x+3} bikes; Tuesday represents {6*x+12}.', 'The difference is 9 bikes.'],'A half-symbol is 3 bikes, not half a bike.','Read the key before treating picture counts as quantities.')
        return task(f'A bar chart axis begins at {5*x}, not zero. Bar A rises 8 units above the baseline and bar B rises 13 units above it. What is the SUM of the two values represented?',10*x+21,[f'The actual values are {5*x+8} and {5*x+13}.',f'Add both values, including both baseline contributions: {10*x+21}.'],'Subtracting heights would correctly give a difference of 5, but would not give their sum.','A truncated axis changes absolute values; identify the requested operation.')
    raise ValueError(k)

def capstone(slot):
    tasks={
    361:task('Make a two-digit number using two different digits from 0,1,2,3,4,5. It must be divisible by 3. How many numbers are possible?',9,['Group the digits by remainder on division by 3: {0,3}, {1,4}, {2,5}. Valid pairs have remainders 0+0 or 1+2.', 'The zero-remainder pair gives only 30 (03 is not two-digit). The 1+2 groups give 2×2×2=8 numbers. Together there are 9.'],'List 12,15,21,24,30,42,45,51,54; the correct count is 9.','Combine disjoint cases with a divisibility rule and the leading-zero restriction.'),
    362:task('Three red packets and two blue packets weigh 48 grams. Three red packets and five blue packets weigh 84 grams. Packets of the same colour have equal weight. How many red packets weigh the same as six blue packets?',9,['Subtract the totals: three blue packets weigh 36 g, so one weighs 12 g. Then three red packets weigh 24 g, so one weighs 8 g.', 'Six blue packets weigh 72 g. At 8 g per red packet, 9 red packets match them.'],'The red:blue weight ratio is 2:3, and both original weighings check.','Cancel a repeated contribution, then use the ratio of the recovered unit weights.'),
    365:task('A 30-cm by 18-cm rectangle contains a triangle using the whole bottom edge and a vertex on the top edge. That triangle is removed. Two thirds of the remaining region is shaded. What area is shaded, in square centimetres?',180,['The rectangle has area 540 cm². The triangle has the same base and height, so it occupies half: 270 cm².', 'The remaining whole is 270 cm², and two thirds of it is 180 cm².'],'The fraction applies to what remains, not to the original rectangle.','Combine an area relationship with a fraction of a changed whole.'),
    366:task('A robot goes from (0,0) to (4,3) using only Right and Up unit moves. It may visit neither (1,1) nor (3,2). How many routes are allowed?',7,['There are C(7,3)=35 routes. Through (1,1): 2×C(5,2)=20. Through (3,2): C(5,2)×2=20.', 'Routes through both were subtracted twice: 2×C(3,1)×2=12. Add them back: 35−20−20+12=7.'],'A small grid filled by adding arrival counts, with zero at each blocked point, also ends at 7.','Count routes in sections, then correct the overlap between forbidden sets.'),
    367:task('A checkerboard has 2 rows and 9 columns. Remove the top-left square and the bottom-right square. Can dominoes tile the remainder? Answer yes or no.','yes',['The removed squares have opposite colours, so the colour counts remain equal. That alone does not prove tileability.', 'Tile columns 2–9 of the top row with four horizontal dominoes, and columns 1–8 of the bottom row with four horizontal dominoes.'],'The construction covers every remaining square once; the colour test was only a necessary condition.','Use the invariant to test an obstruction, then distinguish necessity from a constructive proof.'),
    368:task('A robot begins a route, travels at 12 km/h for 15 minutes, then covers half the distance still remaining. Its final part takes 30 minutes at 10 km/h. How long was the entire route, in kilometres?',13,['The last part is 10×1/2=5 km. Just before the halfway operation there were twice as many kilometres left: 10 km.', 'The first part was 12×1/4=3 km. Add it back to get 13 km.'],'Forward check: after 3 km, 10 remain; half is covered, leaving 5 km for the final half hour.','Convert times to distances, then undo the journey from its final segment.'),
    370:task('A rectangle has positive whole-number side lengths and perimeter 34 cm. What is its greatest possible area in square cm?',72,['The side lengths sum to 17. If the gap is at least 3, moving one unit from the longer to the shorter increases the product.', 'Thus the best integer pair differs by 1: 8 and 9, giving area 72. Every less balanced pair is worse.'],'The pair uses perimeter 34; the strict improvement proves uniqueness up to rotation.','Combine a bound or improvement argument with a proof that no second optimum exists.')}
    if slot==361:
        tasks[slot]['answer']=9
        tasks[slot]['steps'][1]='The zero-remainder pair gives only 30 (03 is not two-digit). The 1+2 groups give 2×2×2=8 numbers. Together there are 9.'
    return tasks.get(slot)

def build(mapping,out):
    counts={};rows=[];manifest=[]
    for s in mapping:
        k=s['skill'];counts[k]=counts.get(k,0)+1;n=counts[k]+2
        for role in ['try','transfer']:
            # Discrete fractional-transfer stories require an even scale.
            nn=2*n if (k=='FRAC-01' and role=='transfer') or (k=='ALG-05' and role=='try') else n
            q=(capstone(s['slot']) if role=='transfer' else None) or family(k,nn,role)
            if k=='FRAC-01' and role=='transfer':q['check']='Send half of the original count, then one third of the remainder; all counts are whole numbers and the final remainder agrees.'
            if k=='ALG-05' and role=='try':q['check']='Subtract the transfer from the first count and add it to the second; check the stated final gap.'
            pid=f'O{s["slot"]:03}{"T" if role=="try" else "X"}'
            # Every standard lesson problem accepts only the final answer.
            # The worked solution still teaches the mathematical reasoning.
            prompt=q['prompt']
            titles={
                ('DIG-01','try'):'Stationery shop: total cost',
                ('DIG-01','transfer'):'Correct the running total',
                ('DIV-03','try'):'Packing bolts into boxes',
                ('ALG-04','try'):'Reverse a number machine',
                ('ALG-04','transfer'):'Pocket money, worked backwards',
                ('DIG-02','try'):'Even numbers from five digits',
                ('DIG-03','transfer'):'Counting printed ticket digits',
                ('DIG-05','try'):'Recover the missing units digit'
            }
            title=titles.get((k,role), 'Practice problem' if role=='try' else 'Transfer challenge')
            rows.append(dict(id=pid,source_type='original_authored',title=title,source_label='Summit One original learning problem',category=k,difficulty=3 if role=='try' else 4,prompt=prompt,answer=q['answer'],unit='',solution_text=q['clue']+'\n\n'+'\n\n'.join(q['steps'])+'\n\n'+q['check']+'\n\nFinal answer: '+str(q['answer']),spoken_script='',rights='original_authored_for_summit_one'))
            manifest.append(dict(id=pid,session=s['slot'],skill=k,role=role,family=k+(':capstone:'+str(s['slot']) if role=='transfer' and capstone(s['slot']) else ':'+role),visit=visit,source_type='original_authored'))
    out.mkdir(parents=True,exist_ok=True)
    (out/'original-problems.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
    (out/'lesson-manifest.json').write_text(json.dumps({'version':'original-transfer-20261112','note':'Different numbers in a repeated family are practice, not evidence of a new structure.','items':manifest},indent=2))
    print(f'Built {len(rows)} protected original challenges for {len(mapping)} lessons across {len(counts)} techniques.')
if __name__=='__main__':build(json.load(open(sys.argv[1])),Path(sys.argv[2]))
